<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import ProductCard from '../components/ProductCard.vue'
import QuantityStepper from '../components/QuantityStepper.vue'
import {shop,productoPorId,formato,agregarCarrito,notificar} from '../stores/shop'
const base=import.meta.env.BASE_URL
const route=useRoute(), talla=ref(''), color=ref(''), cantidad=ref(1), imagen=ref('')
const producto=computed(()=>productoPorId(route.params.id)||productoPorId(shop.ultimo)||shop.productos[0])
watch(producto,p=>{if(p){shop.ultimo=p.id;localStorage.setItem('stilo:ultimo',JSON.stringify(p.id));talla.value='';color.value=p.colors[0]?.[0]||'';cantidad.value=1;imagen.value=p.imgs?.[0]||p.img}}, {immediate:true})
function agregarRapido(p){agregarCarrito(p.id,'M',p.colors[0][0],1);notificar(`${p.name} agregado (talla M)`)}
const relacionadas=computed(()=>producto.value?shop.productos.filter(p=>p.id!==producto.value.id).sort((a,b)=>(a.cat===producto.value.cat?-1:0)-(b.cat===producto.value.cat?-1:0)).slice(0,4):[])
function comprar(){if(!talla.value||!color.value||cantidad.value<1||cantidad.value>10){notificar('Selecciona una talla, un color y una cantidad válida.');return}agregarCarrito(producto.value.id,talla.value,color.value,Number(cantidad.value));notificar(`${producto.value.name} agregado al carrito`)}</script>
<template><section v-if="producto" class="view"><nav class="crumbs" aria-label="Ruta de navegación"><RouterLink to="/inicio">Inicio</RouterLink><i class="fa-solid fa-chevron-right"></i><RouterLink to="/tienda">Tienda</RouterLink><i class="fa-solid fa-chevron-right"></i><span>{{producto.name}}</span></nav><section class="detail"><figure class="gallery"><div class="stage"><img :src="`${base}img/${imagen}`" :alt="producto.name" :data-fit="producto.fit||''"></div><div class="thumbs"><button v-for="(foto,i) in (producto.imgs||[producto.img])" :key="foto" type="button" :class="{on:imagen===foto}" @click="imagen=foto" :aria-label="`Ver foto ${i+1}`"><img :src="`${base}img/${foto}`" alt=""></button></div></figure><article class="detail-info"><span v-if="producto.badge" class="badge badge--static">{{producto.badge}}</span><h1>{{producto.name}}</h1><p class="price price--lg">{{formato(producto.price)}} <s v-if="producto.old">{{formato(producto.old)}}</s></p><p>{{producto.desc}}</p><p class="sold">{{producto.sold.toLocaleString('es-CO')}} personas ya la compraron</p><form @submit.prevent="comprar"><fieldset><legend>Talla</legend><div class="opts"><template v-for="t in ['S','M','L','XL']" :key="t"><input :id="'size-'+t" v-model="talla" type="radio" name="talla" :value="t"><label :for="'size-'+t">{{t}}</label></template></div><small v-if="!talla" class="field-error">Selecciona una talla.</small></fieldset><fieldset class="colors"><legend>Color</legend><div class="opts"><template v-for="(c,i) in producto.colors" :key="c[0]"><input :id="'color-'+i" v-model="color" type="radio" name="color" :value="c[0]"><label :for="'color-'+i" class="sw" :style="{'--c':c[1]}"><span class="sr-only">{{c[0]}}</span></label></template></div></fieldset><div class="field field--row"><span id="lbl-cant">Cantidad</span><QuantityStepper role="group" aria-labelledby="lbl-cant" v-model="cantidad" :min="1" :max="10" /></div><div class="actions"><button class="btn" type="submit"><i class="fa-solid fa-bag-shopping"></i> Agregar al carrito</button><RouterLink class="btn btn--soft" to="/tienda">Seguir comprando</RouterLink></div></form><details open><summary>Cuidado de la prenda</summary><p>Lavar con agua fría y colores similares. No usar blanqueador. Secar a la sombra.</p></details><details><summary>Tallas</summary><p>Disponible en S, M, L y XL. Si tienes dudas, escríbenos por WhatsApp y te ayudamos a elegir.</p></details></article></section><section class="section section--lav"><header class="section-head"><h2>También te puede gustar</h2></header><div class="cards"><ProductCard v-for="p in relacionadas" :key="p.id" :producto="p" @agregar="agregarRapido" /></div></section></section><section v-else class="section"><p>No encontramos el producto.</p><RouterLink class="btn" to="/tienda">Volver a la tienda</RouterLink></section></template>
